ALTER TABLE public.patentes DROP CONSTRAINT IF EXISTS patentes_categoria_chk;
ALTER TABLE public.patentes ADD CONSTRAINT patentes_categoria_chk
  CHECK (categoria IN ('TRANSPORTE', 'REMIS', 'OBRA', 'AUTO'));

ALTER TABLE public.estaciones
  ADD COLUMN IF NOT EXISTS latitud numeric(9, 6),
  ADD COLUMN IF NOT EXISTS longitud numeric(9, 6),
  ADD COLUMN IF NOT EXISTS camino text;

