":"94892129","patente":"PMK414","categoria":"REMIS"},{"pase":"90665137","patente":"AD328WK","categoria":"TRANSPORTE"},{"pase":"99541571","patente":"AF411UY","categoria":"TRANSPORTE"},{"pase":"99541930","patente":"AF436WI","categoria":"TRANSPORTE"},{"pase":"90798242","patente":"OBW823","categoria":"TRANSPORTE"},{"pase":"99561570","patente":"AF509QF","categoria":"TRANSPORTE"},{"pase":"20165477","patente":"AF533SR","categoria":"TRANSPORTE"},{"pase":"99565719","patente":"AF533SR","categoria":"TRANSPORTE"},{"pase":"99594918","patente":"AA946VU","categoria":"TRANSPORTE"},{"pase":"99642507","patente":"AF791ER","categoria":"TRANSPORTE"},{"pase":"99598699","patente":"AF734UP","categoria":"TRANSPORTE"},{"pase":"99642150","patente":"OWB823","categoria":"OBRA"},{"pase":"99657859","patente":"AE733PC","categoria":"TRANSPORTE"},{"pase":"99657949","patente":"AF948ET","categoria":"TRANSPORTE"},{"pase":"99658470","patente":"AF993HA","categoria":"TRANSPORTE"},{"pase":"99656723","patente":"AF136HN","categoria":"TRANSPORTE"},{"pase":"99705864","patente":"AG249HS","categoria":"REMIS"},{"pase":"99738109","patente":"AE454PH","categoria":"TRANSPORTE"},{"pase":"99738712","patente":"AG309CH","categoria":"REMIS"},{"pase":"99779063","patente":"AG533MF","categoria":"REMIS"},{"pase":"99837024","patente":"AB456CU","categoria":"TRANSPORTE"},{"pase":"99739957","patente":"AG309CO","categoria":"TRANSPORTE"},{"pase":"93361395","patente":"AF136HN","categoria":"TRANSPORTE"},{"pase":"99793212","patente":"AG507DK","categoria":"TRANSPORTE"},{"pase":"99694682","patente":"AC912YJ","categoria":"TRANSPORTE"},{"pase":"99756221","patente":"AF740MG","categoria":"AUTO"},{"pase":"99787034","patente":"AG423BT","categoria":"AUTO"},{"pase":"99798784","patente":"AF734US","categoria":"AUTO"},{"pase":"99836690","patente":"AA561YA","categoria":"TRANSPORTE"},{"pase":"92079954","patente":"AF993HK","categoria":"TRANSPORTE"},{"pase":"99691067","patente":"AG110LK","categoria":"TRANSPORTE"},{"pase":"93384377","patente":"MHS385","categoria":"TRANSPORTE"},{"pase":"92093802","patente":"AD985XP","categoria":"TRANSPORTE"},{"pase":"65895016","patente":"AB289LU","categoria":"TRANSPORTE"},{"pase":"99849168","patente":"AG676SP","categoria":"TRANSPORTE"}]$pases$::jsonb)
    AS x(zona text, autopista text, auxiliar text, codigo text, direccion text, latitud text, longitud text, camino text)
)
INSERT INTO public.estaciones (peaje_id, nombre, ubicacion, descripcion, codigos_proveedor, latitud, longitud, camino)
SELECT p.id, f.zona, f.zona, f.direccion, array_remove(ARRAY[f.codigo, f.auxiliar], NULL),
  NULLIF(f.latitud, '')::numeric, NULLIF(f.longitud, '')::numeric, f.camino
FROM fuente f JOIN public.peajes p ON p.nombre = f.autopista
WHERE NOT EXISTS (SELECT 1 FROM public.estaciones e WHERE e.peaje_id = p.id AND e.nombre = f.zona);

WITH claves AS (
  SELECT key AS zona, jsonb_array_elements_text(value) AS alias
  FROM jsonb_each($aliases${"ITUZAINGO":["ITUZAINGO - 02","ITUZAINGO - 03","ITUZAINGO - 04","ITUZAINGO - 05","ITUZAINGO - 25","ITUZAINGO - 28","ITUZAINGO - 29","ITUZAINGO - 30","ITUZAINGO - 31","ITUZAINGO - 32","ITUZAINGO - 41","ITUZAINGO - 42","ITUZAINGO - 43","ITUZAINGO - 44"],"LUJAN":["LUJAN - 01","LUJAN - 03","LUJAN - 06","LUJAN - 12","LUJAN - 13","LUJAN - 15","LUJAN - 16","LUJAN - 17"],"DEL RODEO":["DEL RODEO - 02","DEL RODEO - 04"],"MALVINAS":["MALVINAS - 02","MALVINAS - 04"],"VERGARA":["VERGARA - 02","VERGARA - 07","VERGARA - 08"],"DERQUI":["DERQUI - 03","DERQUI - 05"],"BUEN AYRE":["BUEN AYRE - 02","BUEN AYRE - 03"],"BARCALA":["BARCALA - 05","BARCALA - 06"],"GRAL.RODRIGUEZ":["GRAL.RODRIGUEZ - 02","GRAL.RODRIGUEZ - 04"],"J.J.CASTRO":["J.J.CASTRO - 04"],"BRANDSEN":["BRANDSEN - 04"]}$aliases$::jsonb)
), agrupadas AS (
  SELECT zona, array_agg(alias) AS aliases FROM claves GROUP BY zona
)
UPDATE public.estaciones e
SET codigos_proveedor = (
  SELECT array_agg(DISTINCT codigo ORDER BY codigo)
  FROM unnest(COALESCE(e.codigos_proveedor, ARRAY[]::text[]) || a.aliases) AS codigo
)
FROM agrupadas a, public.peajes p
WHERE p.id = e.peaje_id
  AND p.nombre = 'AUTOPISTA DEL OESTE'
  AND e.nombre = a.zona;

DO $$
DECLARE v_empresa text; v_peaje uuid;
BEGIN
  SELECT id::text INTO v_empresa FROM public.empresas WHERE nombre = 'PROVEEDOR DEMO';
  INSERT INTO public.peajes (nombre, ubicacion, descripcion, empresa_id)
  SELECT 'Corredores Viales Demo SA', 'Buenos Aires', 'Peaje ficticio del ejemplo MVP.', v_empresa
  WHERE NOT EXISTS (SELECT 1 FROM public.peajes WHERE nombre = 'Corredores Viales Demo SA');
  SELECT id INTO v_peaje FROM public.peajes WHERE nombre = 'Corredores Viales Demo SA';
  INSERT INTO public.estaciones (peaje_id, nombre, ubicacion, codigos_proveedor)
  SELECT v_peaje, nombre, ubicacion, ARRAY[codigo] FROM (VALUES
    ('Ricchieri', 'Acceso Ricchieri', '1'),
    ('Tristan Suarez', 'Autopista Ezeiza-Canuelas', '2'),
    ('Monte Grande', 'Acceso Monte Grande', '3'),
    ('Mercado Central', 'Acceso Mercado Central', '5')
  ) AS s(nombre, ubicacion, codigo)
  WHERE NOT EXISTS (SELECT 1 FROM public.estaciones e WHERE e.peaje_id=v_peaje AND e.nombre=s.nombre);
END $$;

DO $$
DECLARE ao text; demo text; p_ao uuid; p_demo uuid; a_ao_fecha uuid; a_ao_pat uuid; a_demo_fecha uuid; a_demo_pat uuid; a_demo_pase uuid;
BEGIN
  SELECT id::text INTO ao FROM public.empresas WHERE nombre='ACCESO OESTE';
  SELECT id::text INTO demo FROM public.empresas WHERE nombre='PROVEEDOR DEMO';

  INSERT INTO public.algoritmos_combinados (nombre, descripcion, empresa_id, estado) VALUES
    ('COMBINAR_FECHA_HORA', 'FECHA + HORA ISO.', ao, 'activa'),
    ('NORMALIZAR_PATENTE', 'Patente de Acceso Oeste.', ao, 'activa'),
    ('COMBINAR_FECHA_HORA', 'Fecha/hora MM/DD/YY HHMMSS.', demo, 'activa'),
    ('NORMALIZAR_PATENTE', 'DOMINIO del Demo.', demo, 'activa'),
    ('NORMALIZAR_PASE', 'DISPOSITIVON a texto.', demo, 'activa')
  ON CONFLICT (nombre, empresa_id) DO UPDATE SET descripcion=EXCLUDED.descripcion, estado='activa';

  SELECT id INTO a_ao_fecha FROM public.algoritmos_combinados WHERE nombre='COMBINAR_FECHA_HORA' AND empresa_id=ao;
  SELECT id INTO a_ao_pat FROM public.algoritmos_combinados WHERE nombre='NORMALIZAR_PATENTE' AND empresa_id=ao;
  SELECT id INTO a_demo_fecha FROM public.algoritmos_combinados WHERE nombre='COMBINAR_FECHA_HORA' AND empresa_id=demo;
  SELECT id INTO a_demo_pat FROM public.algoritmos_combinados WHERE nombre='NORMALIZAR_PATENTE' AND empresa_id=demo;
  SELECT id INTO a_demo_pase FROM public.algoritmos_combinados WHERE nombre='NORMALIZAR_PASE' AND empresa_id=demo;
  DELETE FROM public.algoritmo_combinado_pasos WHERE algoritmo_combinado_id IN (a_ao_fecha,a_ao_pat,a_demo_fecha,a_demo_pat,a_demo_pase);
  INSERT INTO public.algoritmo_combinado_pasos (algoritmo_combinado_id,orden,algoritmo_codigo,parametros) VALUES
    (a_ao_fecha,10,'FORMATEAR_FECHA_HORA','{"columnas_entrada":["FECHA","HORA"],"formato_hora":"YYYY-MM-DD HH:MM:SS"}'),
    (a_ao_pat,10,'BORRAR_ESPACIOS','{"columna":"PATENTE"}'), (a_ao_pat,20,'ELIMINAR_GUIONES','{"columna":"PATENTE_ID"}'), (a_ao_pat,30,'CONVERTIR_MAYUSCULAS','{"columna":"PATENTE_ID"}'),
    (a_demo_fecha,10,'FORMATEAR_FECHA_HORA','{"columnas_entrada":["FECHA","HORA"],"formato_hora":"MM/DD/YY HHMMSS"}'),
    (a_demo_pat,10,'BORRAR_ESPACIOS','{"columna":"DOMINIO"}'), (a_demo_pat,20,'ELIMINAR_GUIONES','{"columna":"PATENTE_ID"}'), (a_demo_pat,30,'CONVERTIR_MAYUSCULAS','{"columna":"PATENTE_ID"}'),
    (a_demo_pase,10,'CONVERTIR_TEXTO','{"columna":"DISPOSITIVON"}');

  INSERT INTO public.plantillas_configuracion (nombre,descripcion,empresa_id,estrategia_codigo,estado) VALUES
    ('ACCESO OESTE - Pasadas','Plantilla 387882.csv.',ao,'ACCESO_OESTE','activa'),
    ('Proveedor Demo - Pasadas','Plantilla 1947768.xlsx.',demo,'PROVEEDOR_DEMO','activa')
  ON CONFLICT (nombre,empresa_id) DO UPDATE SET descripcion=EXCLUDED.descripcion, estrategia_codigo=EXCLUDED.estrategia_codigo, estado='activa';
  SELECT id INTO p_ao FROM public.plantillas_configuracion WHERE nombre='ACCESO OESTE - Pasadas' AND empresa_id=ao;
  SELECT id INTO p_demo FROM public.plantillas_configuracion WHERE nombre='Proveedor Demo - Pasadas' AND empresa_id=demo;
  DELETE FROM public.configuraciones_plantilla WHERE plantilla_id IN (p_ao,p_demo);
  INSERT INTO public.configuraciones_plantilla (plantilla_id,nombre_columna,columna_destino,orden,tipo,algoritmo_combinado_id,configuracion,obligatoria) VALUES
    (p_ao,'FECHA','FECHA_HORA',10,'transformacion',a_ao_fecha,'{"algoritmo_codigo":"FORMATEAR_FECHA_HORA","columnas_entrada":["FECHA","HORA"],"formato_hora":"YYYY-MM-DD HH:MM:SS"}',true),
    (p_ao,'ESTACION','CODIGO_ESTACION',20,'transformacion',NULL,'{"algoritmo_codigo":"COMBINAR_COLUMNAS","columnas_entrada":["ESTACION","VIA"],"separador":" - "}',true),
    (p_ao,'DISPOSITIVO','PASE_ID',30,'transformacion',NULL,'{"algoritmo_codigo":"CONVERTIR_TEXTO","columna":"DISPOSITIVO"}',true),
    (p_ao,'PATENTE','PATENTE_ID',40,'transformacion',a_ao_pat,'{"algoritmo_codigo":"BORRAR_ESPACIOS","columna":"PATENTE"}',true),
    (p_ao,'TARIFA','PRECIO',70,'transformacion',NULL,'{"algoritmo_codigo":"CONVERTIR_NUMERO","columna":"TARIFA"}',true),
    (p_ao,'BONIFICACION','BONIFICACION',80,'transformacion',NULL,'{"algoritmo_codigo":"CONVERTIR_NUMERO","columna":"BONIFICACION"}',true),
    (p_ao,'IMPORTE_NETO','IMPORTE_NETO',90,'transformacion',NULL,'{"algoritmo_codigo":"CALCULAR_IMPORTE_NETO","columnas_entrada":["PRECIO","BONIFICACION"]}',true),
    (p_ao,'QUANTITY','QUANTITY',100,'transformacion',NULL,'{"algoritmo_codigo":"ASIGNAR_VALOR","valor":1}',true),
    (p_demo,'FECHA','FECHA_HORA',10,'transformacion',a_demo_fecha,'{"algoritmo_codigo":"FORMATEAR_FECHA_HORA","columnas_entrada":["FECHA","HORA"],"formato_hora":"MM/DD/YY HHMMSS"}',true),
    (p_demo,'DOMINIO','PATENTE_ID',20,'transformacion',a_demo_pat,'{"algoritmo_codigo":"BORRAR_ESPACIOS","columna":"DOMINIO"}',true),
    (p_demo,'DISPOSITIVON','PASE_ID',30,'transformacion',a_demo_pase,'{"algoritmo_codigo":"CONVERTIR_TEXTO","columna":"DISPOSITIVON"}',true),
    (p_demo,'ESTACION','ESTACION_ID',40,'mapeo',NULL,'{"codigo_proveedor":true}',true),
    (p_demo,'TARIFA','PRECIO',50,'transformacion',NULL,'{"algoritmo_codigo":"CONVERTIR_NUMERO","columna":"TARIFA"}',true),
    (p_demo,'BONIFICACION','BONIFICACION',60,'transformacion',NULL,'{"algoritmo_codigo":"CONVERTIR_NUMERO","columna":"BONIFICACION"}',true),
    (p_demo,'IMPORTE_NETO','IMPORTE_NETO',70,'transformacion',NULL,'{"algoritmo_codigo":"CALCULAR_IMPORTE_NETO","columnas_entrada":["PRECIO","BONIFICACION"]}',true),
    (p_demo,'QUANTITY','QUANTITY',80,'transformacion',NULL,'{"algoritmo_codigo":"ASIGNAR_VALOR","valor":1}',true);
END $$;










